from pathlib import Path
from html import escape
OUT=Path(__file__).parent/'assets'
# All geometry, story and lettering are original; no third-party images or fonts.
def text(x,y,t,size=23): return f'<text x="{x}" y="{y}" stroke="none" font-size="{size}" font-family="sans-serif" fill="#282720">{escape(t)}</text>'
def cat(x,y,s=1):return f'<g transform="translate({x},{y}) scale({s})" stroke="#292720" stroke-width="3" fill="#f8f5eb"><path d="M-25 0 Q-65 -2 -58 40 Q-50 58 -32 42" fill="none"/><ellipse cy="33" rx="33" ry="42"/><path d="M-32 -5 L-29 -48 -8 -29 Q0 -32 10 -29 L31 -48 34 -4 Q26 24 0 23 Q-25 23 -32 -5Z"/><path d="M-17 -6 l8 1 M12 -5 l8 -1 M-3 3 l5 0 -2 4 M-2 9 q-8 7 -13 0 M0 9 q7 7 12 0" fill="none"/><path d="M-38 -1 l-19 -5 M-38 6 l-18 4 M39 -1 l18 -5 M39 6 l18 4"/><path d="M-19 63 l-2 11 M20 63 l1 11"/></g>'
def rain():return ''.join(f'<path d="M{x} {y} l-12 32"/>' for x in range(40,570,47) for y in range(35,320,61))
def buildings():return '<path d="M20 270 V150 H100 V220 H165 V110 H240 V185 H310 V80 H385 V185 H450 V140 H580 V330 H20Z" fill="#cecec3"/>' + ''.join(f'<path d="M{x} 240v30m20-30v30"/>'for x in range(40,560,70))
def book(x,y):return f'<g transform="translate({x},{y})" stroke="#292720" stroke-width="3" fill="#f6f1dc"><path d="M-65 -35 Q-30 -50 0 -25 Q30 -50 65 -35 V45 Q30 32 0 57 Q-30 32 -65 45Z"/><path d="M0 -25 V57 M-54 -23 Q-26 -34 -10 -19 M10 -19 Q35 -34 54 -23" fill="none"/></g>'
def bubble(x,y,t):return f'<rect x="{x}" y="{y}" width="350" height="55" rx="27" fill="#fffdf5" stroke="#292720" stroke-width="2"/>'+text(x+20,y+36,t,21)
def person(x,y):return f'<g transform="translate({x},{y})" stroke="#292720" stroke-width="3"><circle cy="-40" r="29" fill="#f2e9d8"/><path d="M-29 -38Q-39 -90 10 -71Q42 -60 29 -30L10 -53 -29 -38Z" fill="#44443d"/><path d="M-19 -8Q-45 26 -32 78H34Q44 20 19 -8Z" fill="#a7b2a4"/><path d="M-15 78v43M18 78v43"/><path d="M-12 -37h2m18 0h2M-5 -25q8 7 15 0"/></g>'
pages=[]
pages.append(("雨後書店",buildings()+f'<g stroke="#77796f" stroke-width="1" opacity=".6">{rain()}</g>'+text(55,65,'雨下了一整天。',24),'<path d="M50 390H550V670H50Z" fill="#b0b8aa"/><path d="M90 430H510V630H90Z" fill="#f7f3e4"/><path d="M300 430V630M90 565H510"/><path d="M50 390l40-45h420l40 45Z" fill="#343a34"/>'+text(228,420,'雨後書店',22)+cat(410,560,.8)+text(80,715,'小墨在等一個，還沒來的讀者。',24)))
pages.append(("雨中的信",'<path d="M30 40H570V310H30Z" fill="#ece7d9"/>'+cat(160,190,1.1)+'<path d="M270 130H500V260H270Z M270 130L385 213 500 130" fill="#f9f6ea"/>'+text(320,190,'給月亮',24),bubble(70,385,'這封信，好像走錯了。')+cat(410,530,1.3)+book(160,530)+text(60,720,'信裡寫著：外婆的窗，看不到月亮。',23)))
pages.append(("出發",buildings()+'<path d="M30 295Q270 245 570 310" fill="none"/>'+cat(285,210,.8)+text(60,60,'那就借她一點月光。',24),'<path d="M30 650L570 390M30 690L570 430M90 640v-45m70 11v-44m70 12v-44m70 12v-44m70 12v-44m70 12v-44" fill="none"/>'+cat(340,485,.9)+'<path d="M310 490h60v44h-60Z" fill="#d3c9ad"/>'+text(60,720,'小墨帶著最亮的一本書，爬上屋頂。',23)))
pages.append(("借一點月光",'<path d="M30 40H570V320H30Z" fill="#60675f"/><circle cx="430" cy="120" r="58" fill="#dddcc8" stroke="none"/><path d="M30 290H570"/>'+person(190,175)+cat(335,235,.7),bubble(80,390,'可是，書怎麼變成月亮？')+book(285,540)+text(60,720,'「先翻開，再念給她聽。」',24)))
pages.append(("窗邊",'<path d="M30 40H570V320H30Z" fill="#e6ddc8"/><path d="M70 60H220V230H70Z" fill="#67736c"/><path d="M145 60V230M70 140H220"/>'+person(340,185)+book(340,250),'<path d="M30 360H570V740H30Z" fill="#525f55"/><circle cx="300" cy="540" r="137" fill="#eddfad" stroke="none"/>'+book(300,565)+cat(115,640,.6)+'<rect x="45" y="375" width="510" height="55" rx="25" fill="#fffdf5" stroke-width="2"/>'+text(65,411,'故事裡的月光，照亮了整個房間。',23)))
pages.append(("新的讀者",buildings()+'<circle cx="475" cy="80" r="38" fill="#e0c994" stroke="none"/>'+text(60,60,'隔天，雨停了。',24),'<path d="M55 400H545V680H55Z" fill="#aab6a3"/><path d="M80 435H315V630H80Z M355 435H515V680H355Z" fill="#f3eddb"/>'+cat(190,560,.8)+person(430,550)+bubble(60,350,'今天，有沒有太陽的故事？')+text(130,720,'每一本書，都是一扇窗。',25)))
for i,(title,top,bottom) in enumerate(pages,1):
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 800" role="img"><title>{escape(title)}</title><rect width="600" height="800" fill="#f8f5eb"/><g stroke="#292720" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect x="25" y="25" width="550" height="310" fill="#ebe9dd"/>{top}<rect x="25" y="355" width="550" height="390" fill="#f2eddf"/>{bottom}</g>{text(30,778,'雨後書店  /  '+title,13)}{text(550,778,str(i).zfill(2),14)}</svg>'''
 (OUT/f'page-{i}.svg').write_text(svg)
